<script setup>
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import useUserStore from '@/store/modules/user'
import auth from '@/plugins/auth'
import request from '@/utils/request'
import { saveAs } from 'file-saver'
import { ElMessage } from 'element-plus'
const router=useRouter(), user=useUserStore(), summary=ref(null), loading=ref(false), failed=ref(false)
const overview=ref(null), overviewAllowed=auth.hasPermi('equipment:order:viewAll')
const costDates=ref([]), periodCosts=ref(null), periodCostError=ref(false), periodCostLoading=ref(false)
let periodCostVersion=0
async function loadPeriodCosts(){
  const version=++periodCostVersion
  periodCostLoading.value=true;periodCostError.value=false
  try{
    const params=costDates.value?.length===2?{startDate:costDates.value[0],endDate:costDates.value[1]}:{}
    const data=(await request({url:'/equipment/overview/costs',method:'get',params})).data
    if(version===periodCostVersion)periodCosts.value=data
  }catch{if(version===periodCostVersion)periodCostError.value=true}
  finally{if(version===periodCostVersion)periodCostLoading.value=false}
}
const exportingCosts=ref(false)
async function exportCosts(){
  if(periodCostLoading.value || periodCostError.value || !periodCosts.value?.order_count || exportingCosts.value)return
  if(Number(periodCosts.value.order_count)>5000)return ElMessage.warning('单次最多导出 5000 张工单，请缩小日期范围')
  exportingCosts.value=true
  try{
    const params=costDates.value?.length===2?{startDate:costDates.value[0],endDate:costDates.value[1]}:{}
    const file=await request({url:'/equipment/overview/costs/export',method:'get',params,responseType:'blob',timeout:60000})
    if(file.type.split(';')[0]!=='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')return ElMessage.error('导出失败，请重新登录后重试')
    saveAs(file,'维修费用工单.xlsx')
  }finally{exportingCosts.value=false}
}
const costDialog=ref(false),costOrderRows=ref([]),costOrderLoading=ref(false),costOrderMore=ref(false),costOrderDates=ref([])
let costOrderVersion=0
async function loadCostOrders(more=false){
  if(more && costOrderLoading.value)return
  const version=++costOrderVersion,params={}
  if(costOrderDates.value.length===2){params.startDate=costOrderDates.value[0];params.endDate=costOrderDates.value[1]}
  if(more && costOrderRows.value.length)params.beforeId=costOrderRows.value[costOrderRows.value.length-1].id
  costOrderLoading.value=true
  try{
    const rows=(await request({url:'/equipment/overview/costs/orders',method:'get',params})).data||[]
    if(version!==costOrderVersion)return
    costOrderRows.value=more?[...costOrderRows.value,...rows]:rows
    costOrderMore.value=rows.length===50
  }finally{if(version===costOrderVersion)costOrderLoading.value=false}
}
async function showCostOrders(){costOrderDates.value=[...(costDates.value||[])];costOrderRows.value=[];costOrderMore.value=false;costDialog.value=true;await loadCostOrders()}
function closeCostOrders(){costOrderVersion++;costOrderLoading.value=false}
const faults=ref([]), faultsError=ref(false), faultsLoading=ref(false), faultDates=ref([])
let faultRequestVersion=0
async function loadFaults(){const version=++faultRequestVersion;faultsLoading.value=true;faultsError.value=false;try{const params=faultDates.value?.length===2?{startDate:faultDates.value[0],endDate:faultDates.value[1]}:{};const data=(await request({url:'/equipment/overview/faults',method:'get',params})).data||[];if(version===faultRequestVersion)faults.value=data}catch{if(version===faultRequestVersion)faultsError.value=true}finally{if(version===faultRequestVersion)faultsLoading.value=false}}
const exportingFaults=ref(false)
async function exportFaults(){if(faultsLoading.value||faultsError.value||!faults.value.length)return;exportingFaults.value=true;try{const params=faultDates.value?.length===2?{startDate:faultDates.value[0],endDate:faultDates.value[1]}:{};const file=await request({url:'/equipment/overview/faults/export',method:'get',params,responseType:'blob'});if(file.type.split(';')[0]!=='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')return ElMessage.error('导出失败，请重新登录后重试');saveAs(file,'故障代码排行.xlsx')}finally{exportingFaults.value=false}}
const faultDialog=ref(false), faultSelected=ref(null), faultOrderRows=ref([]), faultOrderBusy=ref(false), faultOrderMore=ref(false), faultOrderDates=ref([])
let faultOrderVersion=0
const statusLabels={REPORTED:'待接单',ACCEPTED:'待到场',ARRIVED:'维修中',TESTING:'待试运行',COMPLETED:'待确认',CLOSED:'已关闭',CANCELLED:'已取消'}
async function loadFaultOrders(more=false){if(more&&faultOrderBusy.value)return;const version=++faultOrderVersion;faultOrderBusy.value=true;try{const f=faultSelected.value;const params={code:f.code,category:f.category,part:f.part,symptom:f.symptom};if(faultOrderDates.value.length===2){params.startDate=faultOrderDates.value[0];params.endDate=faultOrderDates.value[1]}if(more&&faultOrderRows.value.length)params.beforeId=faultOrderRows.value[faultOrderRows.value.length-1].id;const data=(await request({url:'/equipment/overview/faults/orders',method:'get',params})).data||[];if(version===faultOrderVersion){faultOrderRows.value=more?[...faultOrderRows.value,...data]:data;faultOrderMore.value=data.length===50}}finally{if(version===faultOrderVersion)faultOrderBusy.value=false}}
async function showFaultOrders(row){faultSelected.value=row;faultOrderDates.value=[...(faultDates.value||[])];faultOrderRows.value=[];faultOrderMore.value=false;faultDialog.value=true;await loadFaultOrders()}
const allowed=auth.hasPermi('equipment:maintenance:list')
async function load(){if(!allowed)return;loading.value=true;failed.value=false;try{summary.value=(await request({url:'/equipment/maintenance/due-summary',method:'get'})).data}catch{failed.value=true}finally{loading.value=false}}
onMounted(async()=>{await load();if(overviewAllowed){try{overview.value=(await request({url:'/equipment/overview',method:'get'})).data}catch{overview.value=null}await Promise.all([loadFaults(),loadPeriodCosts()])}})
</script>
<template>
 <main class="dashboard"><section class="welcome"><div><span class="eyebrow">EQUIPMENT OPERATIONS</span><h1>设备管理工作台</h1><p>{{ user.nickName || user.name }}，欢迎回来。设备现场信息与保养任务在这里汇集。</p></div><div class="badge">设备全生命周期管理</div></section>
 <section v-if="overviewAllowed" class="panel"><div class="panel-head"><div><span class="eyebrow">OVERVIEW</span><h2>设备与维修概况</h2><p>全厂累计数据 · 维修费用按已登记明细统计</p></div></div><div v-if="overview" class="metrics overview"><div class="metric"><strong>{{ overview.equipment.total }}</strong><span>设备总数</span></div><div class="metric warning"><strong>{{ overview.orders.reported }}</strong><span>待接单</span></div><div class="metric"><strong>{{ overview.orders.accepted }}</strong><span>待到场 / 维修中</span></div><div class="metric danger"><strong>{{ overview.orders.completed }}</strong><span>待确认</span></div></div><p v-if="overview" class="cost-summary">累计维修费用 ¥ {{ Number(overview.costs.total).toFixed(2) }} · 人工 ¥ {{ Number(overview.costs.labor).toFixed(2) }} · 配件 ¥ {{ Number(overview.costs.parts).toFixed(2) }} · 其他 ¥ {{ Number(overview.costs.other).toFixed(2) }}</p><el-alert v-else title="统计暂不可用，请刷新重试" type="info" :closable="false"/></section>
 <section v-if="overviewAllowed" class="panel" v-loading="periodCostLoading"><div class="panel-head"><div><span class="eyebrow">REPAIR COSTS</span><h2>维修费用统计</h2><p>按维修日期统计已关联维修记录的费用，含已取消工单；历史未关联费用不计入。无费用的维修不计入下方数量。</p></div></div><el-date-picker v-model="costDates" class="cost-date-filter" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="至" @change="loadPeriodCosts"/><p class="cost-range">{{ costDates?.length === 2 ? costDates.join(' 至 ') : '全部日期' }}</p><el-alert v-if="periodCostError" title="费用统计加载失败，请检查日期范围或重试" type="error" :closable="false"/><div v-else-if="periodCosts" class="metrics overview"><div class="metric"><strong>¥ {{ Number(periodCosts.total).toFixed(2) }}</strong><span>费用合计</span></div><div class="metric"><strong>¥ {{ Number(periodCosts.labor).toFixed(2) }}</strong><span>人工费</span></div><div class="metric"><strong>¥ {{ Number(periodCosts.parts).toFixed(2) }}</strong><span>配件费</span></div><div class="metric"><strong>¥ {{ Number(periodCosts.other).toFixed(2) }}</strong><span>其他费用</span></div></div><p v-if="periodCosts &amp;&amp; !periodCostError" class="cost-range">涉及工单 {{ periodCosts.order_count }} 张 · 有费用的维修记录 {{ periodCosts.repair_count }} 条</p><el-button v-hasPermi="['equipment:order:list']" class="cost-order-button" :disabled="periodCostLoading || periodCostError || !periodCosts?.order_count" @click="showCostOrders">查看费用工单</el-button><el-button class="cost-order-button" :loading="exportingCosts" :disabled="periodCostLoading || periodCostError || !periodCosts?.order_count" @click="exportCosts">导出费用 Excel</el-button></section>
 <section v-if="overviewAllowed" class="panel"><div class="panel-head"><div><span class="eyebrow">FAULTS</span><h2>故障代码排行</h2><p>前 50 项 · 按维修日期和维修记录统计，不含已取消工单；未填写代码的维修不计入</p></div></div><el-date-picker v-model="faultDates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="至" @change="loadFaults"/><el-button :loading="exportingFaults" :disabled="faultsLoading || faultsError || !faults.length" @click="exportFaults">导出 Excel</el-button><el-alert v-if="faultsError" title="故障统计加载失败，请检查日期范围或刷新重试" type="error" :closable="false"/><el-table v-else v-loading="faultsLoading" :data="faults" empty-text="暂无已分类维修记录"><el-table-column prop="code" label="代码" min-width="125"/><el-table-column prop="category" label="类别" min-width="100"/><el-table-column prop="part" label="部位" min-width="100"/><el-table-column prop="symptom" label="现象" min-width="120"/><el-table-column prop="repair_count" label="维修次数" width="95"/><el-table-column prop="order_count" label="工单数" width="85"/><el-table-column label="查看" width="80"><template #default="{row}"><el-button link type="primary" @click="showFaultOrders(row)">工单</el-button></template></el-table-column></el-table></section>
 <section v-if="allowed" class="panel" v-loading="loading"><div class="panel-head"><div><span class="eyebrow">MAINTENANCE</span><h2>保养提醒</h2><p>按北京时间统计当前启用的保养计划</p></div><el-button type="primary" plain @click="router.push('/equipment/maintenance')">查看计划</el-button></div><el-alert v-if="failed" title="保养提醒加载失败，请刷新重试" type="error" :closable="false"/><div v-else class="metrics"><div class="metric danger"><strong>{{ summary?.overdue ?? '—' }}</strong><span>已逾期</span></div><div class="metric warning"><strong>{{ summary?.due_today ?? '—' }}</strong><span>今日到期</span></div></div></section>
 <section class="panel"><span class="eyebrow">QUICK START</span><h2>现场工作</h2><p>在设备台账查看设备二维码，现场人员扫码填写姓名后即可提交巡检或报修。</p><div class="actions"><el-button v-hasPermi="['equipment:asset:list']" @click="router.push('/equipment/assets')">设备台账</el-button><el-button v-hasPermi="['equipment:order:list']" @click="router.push('/equipment/orders')">维修工单</el-button><el-button v-hasPermi="['equipment:inspection:list']" @click="router.push('/equipment/inspections')">巡检记录</el-button></div></section><el-dialog v-model="costDialog" title="费用工单" width="min(95%, 760px)" @closed="closeCostOrders"><p>{{ costOrderDates.length===2 ? costOrderDates.join(' 至 ') : '全部日期' }} · 显示范围内费用，工单详情包含全部记录。</p><div v-loading="costOrderLoading"><el-empty v-if="!costOrderLoading &amp;&amp; !costOrderRows.length" description="暂无费用工单"/><article v-for="row in costOrderRows" :key="row.id" class="cost-order"><strong>#{{ row.id }} · {{ row.equipment_code }} · {{ row.equipment_name }}</strong><p>{{ row.description }}</p><p>{{ statusLabels[row.status] || row.status }} · 合计 ¥ {{ Number(row.total).toFixed(2) }}</p><p>人工 ¥ {{ Number(row.labor).toFixed(2) }} · 配件 ¥ {{ Number(row.parts).toFixed(2) }} · 其他 ¥ {{ Number(row.other).toFixed(2) }}</p><el-button v-hasPermi="['equipment:order:list']" link type="primary" @click="router.push({path:'/equipment/orders',query:{open:row.id}})">查看工单详情</el-button></article><el-button v-if="costOrderMore" :loading="costOrderLoading" @click="loadCostOrders(true)">加载更早工单</el-button></div></el-dialog><el-dialog v-model="faultDialog" title="关联维修工单" width="min(95%, 850px)"><p v-if="faultSelected">{{ faultSelected.code }} · {{ faultSelected.category }} / {{ faultSelected.part }} / {{ faultSelected.symptom }}</p><p>{{ faultOrderDates.length===2 ? faultOrderDates.join(' 至 ') : '累计范围' }} · 同一工单只显示一次</p><el-table v-loading="faultOrderBusy" :data="faultOrderRows" empty-text="没有符合条件的工单"><el-table-column prop="id" label="工单号" width="85"/><el-table-column prop="equipment_code" label="设备编号" min-width="110"/><el-table-column prop="equipment_name" label="设备" min-width="110"/><el-table-column prop="description" label="报修描述" min-width="150"/><el-table-column label="状态" width="105"><template #default="{row}">{{statusLabels[row.status] || row.status}}</template></el-table-column><el-table-column label="详情" width="90"><template #default="{row}"><el-button v-hasPermi="['equipment:order:list']" link type="primary" @click="router.push({path:'/equipment/orders',query:{open:row.id}})">查看详情</el-button></template></el-table-column></el-table><el-button v-if="faultOrderMore" :loading="faultOrderBusy" @click="loadFaultOrders(true)">加载更早工单</el-button></el-dialog></main>
</template>
<style scoped>
.dashboard{max-width:1400px;margin:auto;padding:28px;display:grid;gap:20px;background:#f3f6fa;min-height:100%}.welcome{background:linear-gradient(115deg,#102a43,#1d5574);color:#fff;border-radius:18px;padding:32px;display:flex;align-items:flex-start;justify-content:space-between;gap:20px}.welcome h1{font-size:30px;margin:12px 0}.welcome p{color:#c6d9e5;line-height:1.8;margin:0}.eyebrow{font-size:11px;letter-spacing:.16em;font-weight:700;color:#4c99a8}.welcome .eyebrow{color:#9ad7dc}.badge{border:1px solid #ffffff38;border-radius:30px;padding:9px 16px;white-space:nowrap;color:#d4edf0;font-size:13px}.panel{background:white;border:1px solid #e7edf2;border-radius:16px;padding:26px}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:16px}h2{font-size:20px;color:#18334a;margin:9px 0}p{color:#758697;line-height:1.7;margin:0}.cost-summary{margin-top:18px}.cost-date-filter{margin-top:16px;max-width:100%}.cost-order-button{margin-top:12px}.cost-order{padding:14px 0;border-bottom:1px solid #e6edf5;overflow-wrap:anywhere}.cost-order p{white-space:pre-wrap}.cost-range{margin-top:10px}.overview{flex-wrap:wrap}.overview .metric:not(.danger):not(.warning){background:#eff6f9;color:#23566f}.metrics{display:flex;gap:16px;margin-top:20px}.metric{min-width:155px;display:flex;flex-direction:column;gap:8px;border-radius:12px;padding:20px}.metric strong{font-size:32px}.metric span{font-size:13px}.danger{background:#fff4f1;color:#bd5145}.warning{background:#fff9e9;color:#a8751b}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.actions :deep(.el-button){margin:0}@media(max-width:600px){.dashboard{padding:12px;gap:12px;min-width:0}.welcome{padding:20px;display:block}.welcome h1{font-size:24px}.badge{display:inline-block;margin-top:14px;white-space:normal}.panel{padding:16px;min-width:0;overflow:hidden}.panel-head{align-items:flex-start;flex-wrap:wrap}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:14px}.metric{min-width:0;padding:14px;overflow-wrap:anywhere}.metric strong{font-size:22px}.dashboard :deep(.el-date-editor--daterange){width:100%;max-width:100%;margin:12px 0 0}.dashboard :deep(.el-table){max-width:100%}.cost-order-button{margin-left:0;margin-right:8px}.actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.actions :deep(.el-button){width:100%}.cost-summary{overflow-wrap:anywhere}}
</style>


